args<-commandArgs(TRUE);d<-read.csv(args[1]);m<-glm(y~x1+x2,data=d,family=MASS::negative.binomial(theta=1/.7),control=glm.control(epsilon=1e-16,maxit=1000));X<-model.matrix(m);mu<-exp(drop(X%*%coef(m)));V<-solve(crossprod(X,X*(mu/(1+.7*mu))));jsonlite::write_json(list(beta=coef(m),se=sqrt(diag(V)),n=nobs(m),score=max(abs(crossprod(X,(m$y-mu)/(1+.7*mu))))/nobs(m)),args[2],digits=17,auto_unbox=TRUE)